// Library is a configured scan root bound to a module (arch §9.1).
// StreamsEnabled is the packaged-playback packaging gate (D-8): the column
// defaults ON (every existing library keeps packaging permitted) and PATCH
// /libraries flips it per library; what the flag drives lives in the
// orchestrator, not here (INV-value-agnostic-store).
type Library struct {
	ID             int64
	ModuleID       string
	RootPath       string
	DisplayName    string
	Description    string
	StreamsEnabled bool
	// NamingGroupStyle / NamingElementName are the display-naming knobs
	// (display-naming): two opaque TEXT strings persisted verbatim — the
	// store parses neither. "" is the unset value and doubles as the
	// module-default marker (the module seed's naming wins when empty).
	NamingGroupStyle  string
	NamingElementName string
	CreatedAt         time.Time
}

// FolderCount is one depth-1 relative-path prefix of a library's items with the
// number of items under it. Top-level files report Path "" (LibraryFolders).
type FolderCount struct {
	Path  string
	Items int64
}

// CreateLibrary inserts a library row and returns its new id. The description
// is an optional trailing argument (a POST body may omit the field; it then
// persists as the column default ""). A duplicate (module_id, root_path)
// violates the table's UNIQUE constraint and yields a wrapped error the api
// layer maps to 4xx (T09).
func (s *Store) CreateLibrary(ctx context.Context, moduleID, rootPath, displayName string, description ...string) (int64, error) {
	desc := ""
	if len(description) > 0 {
		desc = description[0]
	}
	res, err := s.db.ExecContext(ctx,
		"INSERT INTO libraries (module_id, root_path, display_name, description, created_at) VALUES (?, ?, ?, ?, ?)",
		moduleID, rootPath, displayName, desc, formatTime(time.Now().UTC()),
	)
	if err != nil {
		return 0, fmt.Errorf("store: create library: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("store: create library last id: %w", err)
	}
	return id, nil
}

// UpdateLibrary applies a partial update to the library row: a nil argument
// leaves the column unchanged (PATCH {display_name?, description?,
// streams_enabled?, naming_group_style?, naming_element_name?}); a non-nil
// pointer overwrites it — including a non-nil "" which stores the empty
// string (the module-default marker for the naming columns). The identity
// columns (module_id, root_path) are NOT updatable here — moving a root
// re-identifies every item and is not an API operation (web-ui-phase-3 D2).
// The naming columns are opaque strings: the store COALESCEs and persists
// them verbatim, parsing nothing (display-naming). A missing row yields a
// wrapped sql.ErrNoRows (the api layer maps it to 404); the updated row is
// returned.
func (s *Store) UpdateLibrary(ctx context.Context, id int64, displayName, description *string, streamsEnabled *bool, namingGroupStyle, namingElementName *string) (Library, error) {
	res, err := s.db.ExecContext(ctx,
		`UPDATE libraries SET
  display_name        = COALESCE(?, display_name),
  description         = COALESCE(?, description),
  streams_enabled     = COALESCE(?, streams_enabled),
  naming_group_style  = COALESCE(?, naming_group_style),
  naming_element_name = COALESCE(?, naming_element_name)
WHERE id = ?`,
		displayName, description, streamsEnabled, namingGroupStyle, namingElementName, id,
	)
	if err != nil {
		return Library{}, fmt.Errorf("store: update library %d: %w", id, err)
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return Library{}, fmt.Errorf("store: update library %d affected: %w", id, err)
	}
	if affected == 0 {
		return Library{}, fmt.Errorf("store: update library %d: %w", id, sql.ErrNoRows)
	}
	return s.GetLibrary(ctx, id)
}

// DeleteLibrary removes a library and every dependent row in ONE transaction:
// the scan results (items, series), their identity-keyed control rows
// (playback_progress, item_parsers, enrichment_failures, and the
// title_overrides of BOTH id spaces — item ids and the series' ser_ ids),
// and the library-scope control rows (scan_jobs, library_parsers,
// metadata_source_prefs — library_id 0 module-scope prefs are another
// library's concern and stay). The libraries row goes last; a missing row
// (0 affected) yields a wrapped sql.ErrNoRows (the api layer maps it to 404).
// The control-table readers are orphan-tolerant (their JOINs skip rows whose
// entity is gone), so a narrower delete could never surface a broken read —
// the delete is total on purpose: a library re-created at the same root
// starts from a clean slate. Files on disk are NEVER touched: store owns
// rows, not media.
func (s *Store) DeleteLibrary(ctx context.Context, id int64) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("store: delete library %d begin: %w", id, err)
	}
	defer tx.Rollback()
	for _, stmt := range []string{
		`DELETE FROM playback_progress    WHERE item_id IN (SELECT id FROM items  WHERE library_id = ?)`,
		`DELETE FROM item_parsers         WHERE item_id IN (SELECT id FROM items  WHERE library_id = ?)`,
		`DELETE FROM enrichment_failures  WHERE item_id IN (SELECT id FROM items  WHERE library_id = ?)`,
		`DELETE FROM title_overrides      WHERE entity_id IN (SELECT id FROM items  WHERE library_id = ?)`,
		`DELETE FROM title_overrides      WHERE entity_id IN (SELECT id FROM series WHERE library_id = ?)`,
		`DELETE FROM items        WHERE library_id = ?`,
		`DELETE FROM series       WHERE library_id = ?`,
		`DELETE FROM scan_jobs    WHERE library_id = ?`,
		`DELETE FROM library_parsers     WHERE library_id = ?`,
		`DELETE FROM metadata_source_prefs WHERE library_id = ?`,
	} {
		if _, err := tx.ExecContext(ctx, stmt, id); err != nil {
			return fmt.Errorf("store: delete library %d: %w", id, err)
		}
	}
	res, err := tx.ExecContext(ctx, `DELETE FROM libraries WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("store: delete library %d: %w", id, err)
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("store: delete library %d affected: %w", id, err)
	}
	if affected == 0 {
		return fmt.Errorf("store: delete library %d: %w", id, sql.ErrNoRows)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: delete library %d commit: %w", id, err)
	}
	return nil
}

// LibrarySummary aggregates a library's persisted, non-deleted items in ONE
// constant-time SQL pass: the count plus the most recent item update stamp
// (the RFC3339Nano TEXT as persisted; "" when the library has no items). A
// missing library yields a wrapped sql.ErrNoRows (the api layer maps it to 404).
//
// The `status <> 'deleted'` exclusion is the one read-side hard-coding of a
// lifecycle literal in store: the canonical status set lives in internal/enrich
// (INV-value-agnostic-store), but the summary contract is defined over
// non-deleted items and store cannot import enrich (INV5). Every other row
// counts regardless of lifecycle state.
func (s *Store) LibrarySummary(ctx context.Context, id int64) (items int64, updatedAt string, err error) {
	if err := libraryExists(ctx, s.db, id); err != nil {
		return 0, "", err
	}
	row := s.db.QueryRowContext(ctx,
		"SELECT COUNT(*), COALESCE(MAX(updated_at), '') FROM items WHERE library_id = ? AND status <> 'deleted'",
		id,
	)
	if err := row.Scan(&items, &updatedAt); err != nil {
		return 0, "", fmt.Errorf("store: library %d summary: %w", id, err)
	}
	return items, updatedAt, nil
}

// LibraryFolders aggregates the library's items into depth-1 relative-path
// prefixes entirely in SQL (no documents loaded): the prefix is the text before
// the first '/', "" for top-level files. Rows are path-ordered; the count
// excludes deleted items (same literal carve-out as LibrarySummary). A missing
// library yields a wrapped sql.ErrNoRows.
func (s *Store) LibraryFolders(ctx context.Context, id int64) ([]FolderCount, error) {
	if err := libraryExists(ctx, s.db, id); err != nil {
		return nil, err
	}
	rows, err := s.db.QueryContext(ctx, `
SELECT CASE WHEN instr(relative_path, '/') = 0
            THEN ''
            ELSE substr(relative_path, 1, instr(relative_path, '/') - 1)
       END AS prefix,
       COUNT(*) AS items
FROM items
WHERE library_id = ? AND status <> 'deleted'
GROUP BY prefix
ORDER BY prefix`, id)
	if err != nil {
		return nil, fmt.Errorf("store: library %d folders: %w", id, err)
	}
	defer rows.Close()
	out := make([]FolderCount, 0)
	for rows.Next() {
		var fc FolderCount
		if err := rows.Scan(&fc.Path, &fc.Items); err != nil {
			return nil, fmt.Errorf("store: library %d folders scan: %w", id, err)
		}
		out = append(out, fc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: library %d folders: %w", id, err)
	}
	return out, nil
}

// SetLibraryChain replaces libraryID's parser chain with pluginIDs, in order:
// position 0..n-1 follows the slice (parser-display). It is FULL replacement —
// chain entries absent from pluginIDs are removed, and an empty (or nil) slice
// clears the chain entirely. The library must exist: a missing libraries row
// yields a wrapped sql.ErrNoRows (the api layer maps it to 404) and NOTHING is
// written. The delete+insert pair runs in one transaction, so a failed write
// can never leave the library half-chained.
//
// The chain is durable per-library state — the footer group order and the
// enrichment queue priority derive from it; the module seed's chain being the
// default when absent is the api layer's concern, not store's.
func (s *Store) SetLibraryChain(ctx context.Context, libraryID int64, pluginIDs []string) error {
	if err := libraryExists(ctx, s.db, libraryID); err != nil {
		return err
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("store: set library chain %d (begin): %w", libraryID, err)
	}
	defer func() { _ = tx.Rollback() }()
	if _, err := tx.ExecContext(ctx,
		"DELETE FROM library_parsers WHERE library_id = ?", libraryID); err != nil {
		return fmt.Errorf("store: set library chain %d (clear): %w", libraryID, err)
	}
	for pos, pluginID := range pluginIDs {
		if _, err := tx.ExecContext(ctx, `
INSERT INTO library_parsers (library_id, plugin_id, position)
VALUES (?, ?, ?)
ON CONFLICT(library_id, plugin_id) DO UPDATE SET
  position = excluded.position`,
			libraryID, pluginID, pos,
		); err != nil {
			return fmt.Errorf("store: set library chain %d/%s: %w", libraryID, pluginID, err)
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: set library chain %d (commit): %w", libraryID, err)
	}
	return nil
}

// GetLibraryChain returns libraryID's parser chain in position order — the
// footer group order and the enrichment queue priority input (parser-display).
// The read JOINs to the library's row, so rows whose library no longer exists
// read as absent — the orphan-tolerant read (the item_parsers pattern). A
// library with no chain (never set, or cleared) also lists empty.
func (s *Store) GetLibraryChain(ctx context.Context, libraryID int64) ([]string, error) {
	rows, err := s.db.QueryContext(ctx, `
SELECT p.plugin_id
FROM library_parsers p
JOIN libraries l ON l.id = p.library_id
WHERE p.library_id = ?
ORDER BY p.position, p.plugin_id`, libraryID)
	if err != nil {
		return nil, fmt.Errorf("store: get library chain %d: %w", libraryID, err)
	}
	defer rows.Close()
	out := make([]string, 0)
	for rows.Next() {
		var pluginID string
		if err := rows.Scan(&pluginID); err != nil {
			return nil, fmt.Errorf("store: get library chain scan: %w", err)
		}
		out = append(out, pluginID)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: get library chain: %w", err)
	}
	return out, nil
}

// libraryExists maps a missing libraries row to the same wrapped sql.ErrNoRows
// the other library reads yield, so every caller's 404 path is one errors.Is
// check.
func libraryExists(ctx context.Context, db *sql.DB, id int64) error {
	var one int
	err := db.QueryRowContext(ctx, "SELECT 1 FROM libraries WHERE id = ?", id).Scan(&one)
	if errors.Is(err, sql.ErrNoRows) {
		return fmt.Errorf("store: library %d: %w", id, err)
	}
	if err != nil {
		return fmt.Errorf("store: library %d exists: %w", id, err)
	}
	return nil
}

// GetLibrary loads a library by id. A missing row yields a wrapped
// sql.ErrNoRows.
func (s *Store) GetLibrary(ctx context.Context, id int64) (Library, error) {
	var (
		l           Library
		createdText string
	)
	row := s.db.QueryRowContext(ctx,
		"SELECT id, module_id, root_path, display_name, description, streams_enabled, naming_group_style, naming_element_name, created_at FROM libraries WHERE id = ?",
		id,
	)
	if err := row.Scan(&l.ID, &l.ModuleID, &l.RootPath, &l.DisplayName, &l.Description, &l.StreamsEnabled, &l.NamingGroupStyle, &l.NamingElementName, &createdText); err != nil {
		return Library{}, fmt.Errorf("store: get library %d: %w", id, err)
	}
	created, err := parseTime(createdText)
	if err != nil {
		return Library{}, fmt.Errorf("store: get library %d parse time: %w", id, err)
	}
	l.CreatedAt = created
	return l, nil
}

// ListLibraries returns every library row ordered id ASC. It takes no filter
// arguments: GET /libraries lists ALL configured scan roots (AC-3). The query
// has no user-supplied args, so the ORDER BY is the only clause (INV1:
// parameterized SQL; nothing is interpolated). A libraries table with zero
// rows yields a non-nil empty slice so the api handler serializes
// {"items":[]} rather than {"items":null} (the JSON contract the admin panel
// library list relies on).
func (s *Store) ListLibraries(ctx context.Context) ([]Library, error) {
	rows, err := s.db.QueryContext(ctx,
		"SELECT id, module_id, root_path, display_name, description, streams_enabled, naming_group_style, naming_element_name, created_at FROM libraries ORDER BY id",
	)
	if err != nil {
		return nil, fmt.Errorf("store: list libraries: %w", err)
	}
	defer rows.Close()
	out := make([]Library, 0)
	for rows.Next() {
		var (
			l           Library
			createdText string
		)
		if err := rows.Scan(&l.ID, &l.ModuleID, &l.RootPath, &l.DisplayName, &l.Description, &l.StreamsEnabled, &l.NamingGroupStyle, &l.NamingElementName, &createdText); err != nil {
			return nil, fmt.Errorf("store: list libraries scan: %w", err)
		}
		created, err := parseTime(createdText)
		if err != nil {
			return nil, fmt.Errorf("store: list libraries parse time: %w", err)
		}
		l.CreatedAt = created
		out = append(out, l)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list libraries: %w", err)
	}
	return out, nil
}
